+(function () {
+  'use strict';
+
+  const ANSWERS = {
+    q1: ['java', 'rust'],
+    q2: ['python', 'cpp', 'ruby'],
+    q3: ['java', 'csharp']
+  };
+
+  const QUESTION_LABELS = {
+    q1: 'Question 1',
+    q2: 'Question 2',
+    q3: 'Question 3'
+  };
+
+  const form = document.getElementById('quiz-form');
+  const resultEl = document.getElementById('result');
+
+  function getSelected(name) {
+    return Array.from(
+      form.querySelectorAll('input[name="' + name + '"]:checked')
+    ).map((el) => el.value);
+  }
+
+  function arraysEqualAsSets(a, b) {
+    if (a.length !== b.length) return false;
+    const setB = new Set(b);
+    return a.every((v) => setB.has(v));
+  }
+
+  form.addEventListener('submit', function (event) {
+    event.preventDefault();
+
+    let score = 0;
+    const detail = [];
+    Object.keys(ANSWERS).forEach((q) => {
+      const selected = getSelected(q);
+      const correct = arraysEqualAsSets(selected, ANSWERS[q]);
+      if (correct) score++;
+      detail.push({
+        label: QUESTION_LABELS[q],
+        correct,
+        selected,
+        answer: ANSWERS[q]
+      });
+    });
+
+    const total = Object.keys(ANSWERS).length;
+
+    const heading = document.createElement('h2');
+    heading.textContent = 'Results';
+
+    const scoreP = document.createElement('p');
+    scoreP.innerHTML =
+      'You got <span class="score">' + score + ' of ' + total + '</span> correct.';
+
+    const list = document.createElement('ul');
+    detail.forEach((d) => {
+      const li = document.createElement('li');
+      const status = d.correct ? '✓ Correct' : '✗ Incorrect';
+      li.textContent =
+        d.label + ': ' + status +
+        ' (correct answers: ' + d.answer.join(', ') + ')';
+      list.appendChild(li);
+    });
+
+    resultEl.replaceChildren(heading, scoreP, list);
+    resultEl.focus?.();
+  });
+})();
+
')

